1	package com.example.starter.gas;
2	
3	import com.example.starter.gas.dto.AssessmentResponse;
4	import com.example.starter.gas.dto.ConfirmRequest;
5	import com.example.starter.gas.dto.ReadingSubmitRequest;
6	import com.example.starter.gas.dto.ReadingSubmitResponse;
7	import com.example.starter.gas.dto.VoucherCreateRequest;
8	import com.example.starter.gas.dto.VoucherResponse;
9	import com.example.starter.gas.service.CustodyService;
10	import com.example.starter.gas.support.MutableClock;
11	import org.junit.jupiter.api.BeforeEach;
12	import org.junit.jupiter.api.Test;
13	import org.springframework.beans.factory.annotation.Autowired;
14	import org.springframework.jdbc.core.JdbcTemplate;
15	
16	import java.math.BigDecimal;
17	import java.time.Instant;
18	import java.time.LocalDate;
19	
20	import static org.assertj.core.api.Assertions.assertThat;
21	
22	/**
23	 * 读数入库 → 凭证生成 → 双方确认 → 偏差考核的主流程，
24	 * 含能量折算、同日唯一、双方确认、3% 恰免考、读数乱序归位、幂等等场景。
25	 */
26	class CustodyMainFlowTest extends AbstractH2IntegrationTest {
27	
28	    private static final LocalDate GAS_DAY = LocalDate.of(2026, 9, 20);
29	
30	    @Autowired
31	    private CustodyService custodyService;
32	    @Autowired
33	    private JdbcTemplate jdbc;
34	    @Autowired
35	    private MutableClock clock;
36	
37	    @BeforeEach
38	    void setUp() {
39	        resetDatabase(jdbc);
40	        addNomination(jdbc, GAS_DAY, "10000.00");
41	    }
42	
43	    private ReadingSubmitResponse reading(String requestId, String meterTime,
44	                                          String volume, String hv) {
45	        return custodyService.submitReading(new ReadingSubmitRequest(requestId, "ST01",
46	                Instant.parse(meterTime), new BigDecimal(volume), new BigDecimal(hv)));
47	    }
48	
49	    @Test
50	    void fullFlow_readingsVoucherBothConfirmAndAssessment_atExactThreePercentExempt() {
51	        // 气量日当日（2026-09-20 UTC）分两段读数，乱序提交（晚间读数先入库）
52	        clock.setInstant(Instant.parse("2026-09-20T20:00:00Z"));
53	        var evening = reading("rd-evening", "2026-09-20T20:00:00Z", "4000", "38.000000");
54	        clock.setInstant(Instant.parse("2026-09-20T12:05:00Z"));
55	        var morning = reading("rd-morning", "2026-09-20T12:00:00Z", "6000", "40.000000");
56	        assertThat(evening.duplicated()).isFalse();
57	        assertThat(morning.duplicated()).isFalse();
58	        // 均按表底时刻归位到同一气量日
59	        assertThat(evening.gasDate()).isEqualTo(GAS_DAY);
60	        assertThat(morning.gasDate()).isEqualTo(GAS_DAY);
61	
62	        // 气量日未结束不能生成凭证
63	        ApiException early = catchApi(() -> custodyService.createVoucher(
64	                new VoucherCreateRequest("vc-1", "ST01", GAS_DAY)));
65	        assertThat(early.getCode()).isEqualTo("GAS_DAY_NOT_CLOSED");
66	
67	        // 24:00（UTC）后生成凭证
68	        clock.setInstant(Instant.parse("2026-09-21T00:05:00Z"));
69	        VoucherResponse voucher = custodyService.createVoucher(
70	                new VoucherCreateRequest("vc-1", "ST01", GAS_DAY));
71	        assertThat(voucher.volume()).isEqualByComparingTo("10000.0000");
72	        // (6000×40 + 4000×38)/10000 = 39.2
73	        assertThat(voucher.weightedHeatingValue()).isEqualByComparingTo("39.200000");
74	        // 体积×加权热值 = 392000.00
75	        assertThat(voucher.energy()).isEqualByComparingTo("392000.00");
76	        assertThat(voucher.status()).isEqualTo("DRAFT");
77	
78	        // 单方确认不生效
79	        VoucherResponse afterA = custodyService.confirm(voucher.voucherNo(),
80	                new ConfirmRequest("cf-a", "A"));
81	        assertThat(afterA.status()).isEqualTo("PARTIALLY_CONFIRMED");
82	        assertThat(afterA.firstConfirmParty()).isEqualTo("A");
83	
84	        // B 方确认后生效
85	        VoucherResponse effective = custodyService.confirm(voucher.voucherNo(),
86	                new ConfirmRequest("cf-b", "B"));
87	        assertThat(effective.status()).isEqualTo("EFFECTIVE");
88	        assertThat(effective.effectiveDate()).isEqualTo(LocalDate.of(2026, 9, 21));
89	    }
90	
91	    @Test
92	    void sameStationSameGasDay_onlyOneVoucher() {
93	        prepareEffectiveVoucher();
94	
95	        ApiException ex = catchApi(() -> custodyService.createVoucher(
96	                new VoucherCreateRequest("vc-dup", "ST01", GAS_DAY)));
97	        assertThat(ex.getStatus().value()).isEqualTo(409);
98	        assertThat(ex.getCode()).isEqualTo("VOUCHER_ALREADY_EXISTS");
99	
100	        Integer voucherCount = jdbc.queryForObject(
101	                "SELECT COUNT(1) FROM custody_voucher WHERE station_code='ST01' AND gas_date=? "
102	                        + "AND voucher_type='ORIGINAL'", Integer.class, java.sql.Date.valueOf(GAS_DAY));
103	        assertThat(voucherCount).isEqualTo(1);
104	    }
105	
106	    @Test
107	    void idempotency_sameKeySameParamsReturnsFirstResult_sameKeyDifferentParamsConflicts() {
108	        clock.setInstant(Instant.parse("2026-09-20T10:00:00Z"));
109	        var first = reading("idem-rd", "2026-09-20T10:00:00Z", "1000", "39.000000");
110	        // 同键同参：返回首次结果快照（首次为新写入，duplicated=false）
111	        var retry = custodyService.submitReading(new ReadingSubmitRequest("idem-rd", "ST01",
112	                Instant.parse("2026-09-20T10:00:00Z"), new BigDecimal("1000"), new BigDecimal("39.000000")));
113	        assertThat(retry.readingId()).isEqualTo(first.readingId());
114	        assertThat(retry.duplicated()).isEqualTo(first.duplicated());
115	        assertThat(retry).isEqualTo(first);
116	
117	        // 同键异参：409 且无新版本/新读数
118	        ApiException conflict = catchApi(() -> custodyService.submitReading(
119	                new ReadingSubmitRequest("idem-rd", "ST01",
120	                        Instant.parse("2026-09-20T11:00:00Z"),
121	                        new BigDecimal("2000"), new BigDecimal("39.000000"))));
122	        assertThat(conflict.getStatus().value()).isEqualTo(409);
123	        assertThat(conflict.getCode()).isEqualTo("IDEMPOTENCY_CONFLICT");
124	        Integer count = jdbc.queryForObject("SELECT COUNT(1) FROM meter_reading", Integer.class);
125	        assertThat(count).isEqualTo(1);
126	    }
127	
128	    @Test
129	    void lateReading_afterDayBoundary_goesToDiffAndDoesNotChangeVoucher() {
130	        // 24:00 前入库一段读数
131	        clock.setInstant(Instant.parse("2026-09-20T23:50:00Z"));
132	        reading("rd-on-time", "2026-09-20T23:00:00Z", "5000", "40.000000");
133	        clock.setInstant(Instant.parse("2026-09-21T00:05:00Z"));
134	        VoucherResponse voucher = custodyService.createVoucher(
135	                new VoucherCreateRequest("vc-late", "ST01", GAS_DAY));
136	        assertThat(voucher.volume()).isEqualByComparingTo("5000.0000");
137	
138	        // 24:00 后才入库、但表底时刻仍属 20 日的迟到读数：不改凭证
139	        clock.setInstant(Instant.parse("2026-09-21T01:00:00Z"));
140	        reading("rd-late", "2026-09-20T21:00:00Z", "3000", "35.000000");
141	        VoucherResponse unchanged = custodyService.getVoucher(voucher.voucherNo());
142	        assertThat(unchanged.volume()).isEqualByComparingTo("5000.0000");
143	        assertThat(unchanged.energy()).isEqualByComparingTo("200000.00");
144	
145	        Integer diffCount = jdbc.queryForObject(
146	                "SELECT COUNT(1) FROM voucher_reading_diff WHERE voucher_no=?",
147	                Integer.class, voucher.voucherNo());
148	        assertThat(diffCount).isEqualTo(1);
149	    }
150	
151	    @Test
152	    void assessment_isStableOnRecomputeAndThreePercentBoundaryExempt() {
153	        prepareEffectiveVoucher();
154	
155	        // 实际能量 392000，指定能量按比例换算使偏差恰为 3%：
156	        // 指定 N 满足 |392000 - N| = 0.03 N → N = 392000/1.03 ≈ 380582.52
157	        jdbc.update("UPDATE daily_nomination SET nominated_energy=380582.52 WHERE gas_date=?",
158	                java.sql.Date.valueOf(GAS_DAY));
159	
160	        AssessmentResponse first = custodyService.assessDay("ST01", GAS_DAY);
161	        // |392000 - 380582.52| = 11417.48；3% × 380582.52 = 11417.4756 → 11417.48
162	        assertThat(first.deviationAbs()).isEqualByComparingTo("11417.48");
163	        assertThat(first.toleranceEnergy()).isEqualByComparingTo("11417.48");
164	        assertThat(first.exempt()).isTrue();
165	        assertThat(first.penalty()).isEqualByComparingTo("0.00");
